await page.addInitScript((cs: string) => {
  const w = window as unknown as { __ups?: unknown[]; __sents?: unknown[] };
  w.__ups = [];
  w.__sents = [];
  const Orig = window.WebSocket;
  window.WebSocket = class extends Orig {
    constructor(...args: ConstructorParameters<typeof Orig>) {
      super(...args);
      this.addEventListener('message', (ev: MessageEvent) => {
        try {
          const m = JSON.parse(String(ev.data));
          if (m.type !== 'entity_update') return;
          const me = (m.payload?.entities ?? []).find(
            (t: { kind?: string; callsign?: string }) => t.kind === 'ship' && t.callsign === cs,
          );
          if (me) w.__ups?.push({ regime: me.regime, flightRegime: me.flightRegime, pos: me.pos });
        } catch {
          // ignore
        }
      });
      const origSend = this.send.bind(this);
      this.send = (data: string) => {
        try {
          const m = JSON.parse(String(data));
          if (m.type === 'input') {
            w.__sents?.push({ seq: m.payload?.seq, p: m.payload, at: performance.now() });
          }
        } catch {
          // ignore
        }
        return origSend(data);
      };
    }
  };
}, callsign);

